"use strict";(self.webpackChunknexwall_endpoint_doc=self.webpackChunknexwall_endpoint_doc||[]).push([["6582"],{7446(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"design":[{"type":"link","href":"/nexwall-endpoint-doc/docs/design/overview","label":"Overview","docId":"design/overview","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/architecture","label":"Architecture","docId":"design/architecture","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/components","label":"Components","docId":"design/components","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/data-model","label":"Data model","docId":"design/data-model","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/identity-and-tenancy","label":"Identity and tenancy","docId":"design/identity-and-tenancy","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/policy","label":"Policy","docId":"design/policy","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/response-and-firewall","label":"Response and firewall","docId":"design/response-and-firewall","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/api","label":"APIs","docId":"design/api","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/security-and-licensing","label":"Security and licensing","docId":"design/security-and-licensing","unlisted":false},{"type":"link","href":"/nexwall-endpoint-doc/docs/design/status","label":"Status","docId":"design/status","unlisted":false}]},"docs":{"design/api":{"id":"design/api","title":"APIs","description":"Nexwall Endpoint has two interfaces served by the Controller. Both are described by OpenAPI 3.1 documents, and the build fails if a document and the running code disagree about which routes exist or who may call them.","sidebar":"design"},"design/architecture":{"id":"design/architecture","title":"Architecture","description":"Nexwall Endpoint is a composed platform with a thin owned core. The layers below show where each part lives.","sidebar":"design"},"design/components":{"id":"design/components","title":"Components","description":"Nexwall Endpoint is composed of open-source building blocks and Nexwall\'s own code. The table shows what is used for what, and under which licence.","sidebar":"design"},"design/data-model":{"id":"design/data-model","title":"Data model","description":"Every event leaves the agent in the same wrapper (the envelope) with a payload described by the Open Cybersecurity Schema Framework (OCSF), version 1.10.0. The version is pinned, and class numbers are checked by automated tests.","sidebar":"design"},"design/identity-and-tenancy":{"id":"design/identity-and-tenancy","title":"Identity and tenancy","description":"How a device proves who it is","sidebar":"design"},"design/overview":{"id":"design/overview","title":"Overview","description":"Nexwall Endpoint is under development and has not been released. This page describes the design. Anything marked as a target is a goal that has not been measured yet. The Status page lists what has been built and verified.","sidebar":"design"},"design/policy":{"id":"design/policy","title":"Policy","description":"Policy tells each agent how to configure the endpoint and its sensors. It is signed by the Controller, checked by the agent, and applied module by module with a rollback if something fails.","sidebar":"design"},"design/response-and-firewall":{"id":"design/response-and-firewall","title":"Response and firewall","description":"The most distinctive part of the design is the loop between the endpoint and the network. When a device is compromised, it can be cut off in two places at once: on the device itself and at the firewall that protects the network.","sidebar":"design"},"design/security-and-licensing":{"id":"design/security-and-licensing","title":"Security and licensing","description":"Security of the product itself","sidebar":"design"},"design/status":{"id":"design/status","title":"Status","description":"Nexwall Endpoint is in development. Progress is published in the release notes. This page summarises it in the same terms.","sidebar":"design"}}}}')}}]);